test('toggles transaction fields with ± button', async ({ browser }) => {
  const page = await browser.newPage();
  await page.goto('/');

  const plusMinus = page.getByText('±');
  await expect(plusMinus).toBeVisible();
  await expect(page.locator('field')).toHaveCount(0);

  await plusMinus.click();
  await expect(page.locator('field')).toHaveCount(5);

