import { test, expect } from './fixtures';

test('renames an account and filters transactions', async ({ page }) => {
  await page.goto('/');
  await page.getByText('Bank of America', { exact: true }).click();
  await expect(page).toHaveURL(/\/accounts\//);

  const titleInput = page.getByRole('textbox', { name: /account name/i });
  await titleInput.fill('Renamed Account');
  await titleInput.press('Enter');
  await expect(page.getByRole('heading', { name: 'Renamed Account' })).toBeVisible();

  const search = page.getByRole('textbox', { name: /search/i });
  await search.fill('Kroger');

  const category = page.getByRole('combobox', { name: /category/i });
  await category.selectOption({ label: 'Food' });

  await expect(page.getByText('Kroger')).toBeVisible();
});

