test('mobile page header renders three buttons and they are interactive', async ({ page }) => {
  await page.setViewportSize({ width: 350, height: 600 });
  await page.goto('/');

  const mobileHeader = page.locator('mobilepageheader');
  await expect(mobileHeader).toBeVisible();

  const headerButtons = mobileHeader.locator('button');
  await expect(headerButtons).toHaveCount(3);

  for (let i = 0; i < 3; i++) {
    const button = headerButtons.nth(i);
    await expect(button).toBeVisible();
    await button.click();
    await expect(mobileHeader).toBeVisible();
  }
});

